select
user.*
from user user

    and user.id = #{id}
    and user.username = #{username}
    and user.password = #{password}
    and user.nick_name like concat('%',#{nickName},'%')
    and user.avatar = #{avatar}
    and user.age = #{age}
    and user.sex = #{sex}
    and user.tel = #{tel}
    and user.info = #{info}
    and user.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from user user

    and user.id = #{id}
    and user.username = #{username}
    and user.password = #{password}
    and user.nick_name like concat('%',#{nickName},'%')
    and user.avatar = #{avatar}
    and user.age = #{age}
    and user.sex = #{sex}
    and user.tel = #{tel}
    and user.info = #{info}
    and user.create_time = #{createTime}
